/* Approved A1 implementation proposal. All native outcomes remain unmeasured. */
const PLAN_TRACES = [
 {id:'input',label:'Đầu vào',summary:'RGB · câu lệnh · state',title:'Robot thực sự nhìn và nhận gì?',body:'Giữ ảnh gốc và ảnh sau xử lý, câu lệnh, trạng thái robot, camera và thời điểm của từng input. Dữ liệu phải cùng một lượt chạy và được căn thời gian.',check:'Kiểm crop, calibration, tọa độ và timing trước khi quy lỗi cho mô hình.'},
 {id:'vlm',label:'VLM',summary:'Features · masks · phiên bản',title:'Xem output thật của VLM',body:'Thu biểu diễn và masks tại ranh giới VLM → Action Expert, kèm layer, shape và phiên bản. Text hay grounding chỉ xuất hiện khi model thực sự cung cấp; không thêm một “ý định” do người viết tưởng tượng.',check:'Probe có nhãn giúp kiểm giả thuyết. Đọc được thông tin trong latent chưa chứng minh Action Expert sử dụng nó.'},
 {id:'action',label:'Action Expert',summary:'Action chunk · state · horizon',title:'Model đã dự đoán hành động nào?',body:'Giữ conditioning, trạng thái, sampling seed và chuỗi action cuối của inference cùng units, normalization và horizon. Đối chiếu với lệnh thực thi, không coi vector field lúc training là command.',check:'Cùng input và sampling seed cần kiểm kết quả trước/sau reload và giữa chế độ debug với inference thực.'},
 {id:'execution',label:'Thực thi',summary:'Command gửi · response đo',title:'Robot có làm theo action đã dự đoán?',body:'Ghi action trước và sau binding, clipping, hàng đợi, thời điểm gửi và trạng thái/contact robot đáp lại. Prediction, command và response là ba loại bằng chứng riêng.',check:'Nếu lệnh bị đổi hoặc controller không theo được: sửa hệ thống và lập lại baseline trước khi thử dữ liệu.'},
 {id:'outcome',label:'Kết quả',summary:'Đã thử · lỗi · chưa rõ · chưa tới',title:'Chấm kết quả độc lập với policy',body:'Scorer dùng geometry, trạng thái vật và contact để chấm đúng vật, giữ vật, đặt, nhả và rút. Bước chưa tới không là fail; thiếu verifier không là pass. Timeout tính là thất bại toàn task.',check:'So case lỗi, toàn task từ trạng thái tự nhiên, điều kiện trước đó tốt và tập final giữ riêng.'}
];

function openingTaskContract(){const t=SKILL_PLAN_SPEC.draft_thresholds_not_measurements,g=SKILL_PLAN_SPEC.geometry_proposal;return `<section class="plan-task" id="a1-task" aria-labelledby="a1-title">
 <header><span class="opening-kicker">MỘT TASK · MỘT TIÊU CHUẨN RÕ RÀNG</span><h2 id="a1-title">Đúng vật. Đúng ô.<br>Nhả rồi rút tay.</h2><p>Example xuyên suốt: lấy linh kiện vàng và đặt vào A1. Đội thử gắp–đặt vật cứng trong mô phỏng; task owner chốt vùng thao tác và yêu cầu trước khi nghiệm thu.</p></header>
 <div class="plan-task-grid"><figure class="plan-target"><svg viewBox="0 0 640 360" role="img" aria-labelledby="a1-diagram-title"><title id="a1-diagram-title">Sơ đồ tiêu chuẩn đặt: toàn bộ footprint của linh kiện nằm trong vùng A1, đã nhả và vật ổn định. Geometry đề xuất, không phải kết quả đo.</title><defs><pattern id="a1-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#dce6f1"/></pattern><marker id="a1-arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="none" stroke="#7890ae"/></marker></defs><rect width="640" height="360" rx="12" fill="#f3f7fc"/><text x="25" y="30" fill="#62758c" font-size="14">SƠ ĐỒ MINH HỌA · NHÌN TỪ TRÊN</text><rect x="280" y="76" width="320" height="240" rx="6" fill="url(#a1-grid)" stroke="#789abf" stroke-width="2"/><rect x="289" y="85" width="302" height="222" rx="3" fill="none" stroke="#4b8c70" stroke-dasharray="7 5"/><text x="280" y="62" fill="#365879" font-size="16">A1 · vùng trong ${g.target_inner_rectangle_mm.join(' × ')} mm</text><rect x="360" y="146" width="160" height="100" rx="4" fill="#f0c14b" stroke="#b9902f" stroke-width="2"/><text x="440" y="190" text-anchor="middle" fill="#5e4a16" font-size="15">Linh kiện</text><text x="440" y="213" text-anchor="middle" fill="#5e4a16" font-size="14">${g.part_box_mm.slice(0,2).join(' × ')} mm</text><path d="M100 112H170V173H143M203 173H176" fill="none" stroke="#7189a7" stroke-width="13" stroke-linecap="round"/><path d="M198 218H264" stroke="#7890ae" stroke-width="2" marker-end="url(#a1-arrow)"/><text x="53" y="265" fill="#62758c" font-size="14">Tay rút khỏi vật</text><text x="280" y="341" fill="#62758c" font-size="14">Footprint nằm trọn trong A1 · không yêu cầu yaw trong MVP</text></svg><figcaption>Geometry để thử: ${g.part_box_mm.join(' × ')} mm. Hình giải thích tiêu chuẩn, không là ảnh robot đã đạt.</figcaption></figure>
 <div class="plan-acceptance"><ol><li><span>01</span><div><strong>Lấy đúng linh kiện</strong><p>Đúng ID vật; kiểm giữ bằng pose, contact và chuyển động đo được.</p></div></li><li><span>02</span><div><strong>Nằm hoàn toàn trong A1</strong><p>Chấm footprint và mặt đỡ thực, không chỉ vị trí một điểm tâm.</p></div></li><li><span>03</span><div><strong>Đã nhả, vật ổn định, tay đã rút</strong><p>Không còn contact tay–vật; đo độ ổn định và khoảng rút tay.</p></div></li></ol><div class="plan-task-targets"><div><strong>${t.episode_deadline_s}s</strong><span>Thời hạn thử</span></div><div><strong>${t.settle_duration_s}s</strong><span>Ổn định sau nhả</span></div><div><strong>A1</strong><span>Vùng đích</span></div></div><p class="plan-note">Các kích thước và ngưỡng là đề xuất cho prototype; cần calibration và task owner chốt. Chưa là chuẩn nhà máy hoặc kết quả đã đo.</p></div></div>
 </section>`;}

function openingNativeBaseline(){return `<section class="plan-baseline" id="native-baseline" aria-labelledby="native-baseline-title"><header><span class="opening-kicker">BƯỚC ĐẦU TIÊN · ROBOT-DATA-ONLY</span><h2 id="native-baseline-title">Một baseline chạy thật,<br>rồi mới thử thêm nguồn.</h2><p>Kiểm một task GR1 có sẵn để xác nhận model và controller tương thích, sau đó port A1. Hai kết quả được ghi riêng.</p></header><ol class="plan-baseline-flow">${[['Batch hợp lệ','Ảnh, state, action đúng robot'],['Training','Loss, gradient và update thật'],['Checkpoint','Lưu model cùng recipe'],['Reload','Đối chiếu inference'],['Closed-loop','Action → command → response'],['Scorer','Chấm độc lập toàn task']].map(([title,body],i)=>`<li><span>0${i+1}</span><strong>${title}</strong><small>${body}</small></li>`).join('')}</ol><p class="plan-note">Native VLA / GR1 hiện chưa có receipts chạy của đội; baseline chạy đúng là gate bắt buộc trước phép so nguồn.</p><aside class="plan-cold-start"><strong>Nếu robot fail ngay từ đầu thì sao?</strong><p>Kiểm expert có làm được task và controller / binding có đúng trước. Nếu kỹ năng nền chưa có: thu seed, chia curriculum khả thi trong budget. Nếu vẫn không đạt: thu hẹp scope hoặc hoãn; không training vô hạn. Bước chưa tới giữ “chưa thử”, không gán fail cả chuỗi.</p></aside><details class="opening-more"><summary>Native binding khác ví dụ MuJoCo thu nhỏ như thế nào?<span>Đúng chiều tensor chưa đủ để robot thực thi đúng.</span></summary><div class="opening-map-detail"><p>Config tham chiếu GR1 có action 29D, chunk 16 và padding 32 trong head. Phải pin camera, state/action order, units, absolute/delta, normalization và control timing. Không padding action 4D của reference thành action robot 29D; không ép các khớp còn lại về 0. <a href="https://github.com/FluxVLA/FluxVLA/blob/main/configs/gr00tn15/gr00tn15_eagle_3b_robocasa_30_eps_full_finetune.py" target="_blank" rel="noopener">Config tham chiếu FluxVLA →</a></p><p>Task compatibility đề xuất: <code>PosttrainPnPNovelFromTrayToPlateSplitA</code>. Pass task đó chỉ kiểm đường native, chưa nghiệm thu A1. Một tay / torso cố định cần binding hợp lệ trước khi dùng.</p><p>Hiện máy kiểm có MuJoCo và reference; chưa có GPU khả dụng, FluxVLA hoặc native checkpoint. Hook VLM và action phải kiểm parity với inference thực.</p></div></details></section>`;}

function openingSourceRecipes(){return `<section class="plan-sources" id="source-recipes" aria-labelledby="source-recipes-title"><header><span class="opening-kicker">GIẢM CÔNG THU MẪU · KIỂM BẰNG DOWNSTREAM</span><h2 id="source-recipes-title">Human và synthetic<br>dạy robot bằng cách nào?</h2><p>Mẫu robot tạo baseline. Synthetic mở rộng tình huống bằng quỹ đạo thực thi. Human motion có thể dạy chuyển động qua bridge phù hợp. Mỗi nguồn có gate và phép đo riêng.</p></header><div class="plan-source-tabs" role="group" aria-label="Chọn recipe dữ liệu">${[['R','Mẫu robot','Baseline'],['S','Synthetic','Pilot đầu'],['H','Human motion','Pilot có điều kiện']].map(([id,title,sub])=>`<button type="button" data-plan-source="${id}" aria-pressed="${id==='S'}" aria-controls="source-recipe-body"><span>${id}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div id="source-recipe-body"></div><div class="plan-study" id="source-study" aria-live="polite"></div></section>`;}

function planRecipeBody(source){if(source==='R')return `<div class="plan-recipe-grid"><figure><img src="assets/story/task-start.png" width="1672" height="941" alt="Robot trong task A1, hình minh họa." loading="lazy"><figcaption>Mẫu robot đích · Hình minh họa</figcaption></figure><div><span class="plan-chip">NỀN TẢNG CHUNG</span><h3>Robot dạy hành động đúng embodiment</h3><p>Thu seed thành công với ảnh, state, action đã gửi và response. Calibration, correction và công reset đều được ghi.</p>${planRecipeSteps(['Seed robot hợp lệ','QA + split theo roots','Native action loss','Reload + rollout cả task'])}<p class="plan-note">Failed policy action không tự thành positive imitation target. Bản thử đầu đề xuất 20 training seed roots; còn phải benchmark, tính cả roots dùng để hiệu chuẩn và chọn model.</p></div></div>`;
 if(source==='S')return `<div class="plan-recipe-grid"><figure><img src="assets/story/task-start.png" width="1672" height="941" alt="Cảnh robot gắp đặt làm tham chiếu cho synthetic execution, hình minh họa." loading="lazy"><figcaption>Synthetic execution · Native generator cần port</figcaption></figure><div><span class="plan-chip">PILOT ĐẦU · CHƯA CHẠY NATIVE</span><h3>Sinh quỹ đạo, cho robot thực thi, rồi mới lấy nhãn</h3><p>Biến đổi object / target frame từ training seed trong vùng với tới. Controller thực thi trong physics; lưu action, response, contact và kết quả.</p>${planRecipeSteps(['Seed + biến đổi khả thi','Controller thực thi','QA → nhận / từ chối','R + S → train và đo'])}<p class="plan-note">Video được sinh chưa tự có measured robot actions. Lượt sai vẫn lưu để tính công; nhiều variants vẫn cùng seed ancestor. Final không vào generator.</p></div></div><details class="opening-more"><summary>Kiểm nhãn action của synthetic ở đâu?<span>Profile, geometry, contact và outcome phải đúng.</span></summary><div class="opening-map-detail"><p>Giữ desired action, command đã gửi và response đo riêng. Kiểm units/frame/timing, controller tracking và task constraints trước khi nhận positive release. Reference hiện dùng weld để gắp; không thay contact-valid execution của GR1.</p><p>Appearance augmentation chỉ kế thừa action khi hình học và ý nghĩa thao tác còn đúng. Nó không tự mở coverage chuyển động. <a href="https://mimicgen.github.io/docs/modules/task_spec.html" target="_blank" rel="noopener">Tiền lệ MimicGen →</a></p></div></details>`;
 return `<div class="plan-recipe-grid"><figure><img src="assets/story/human-demo.png" width="1672" height="941" alt="Người làm mẫu thao tác, hình minh họa cho nguồn human motion." loading="lazy"><figcaption>Human egocentric · Cần RGB, pose, camera và timing hợp lệ</figcaption></figure><div><span class="plan-chip">CANDIDATE MOTOR PILOT · CHƯA TÍCH HỢP</span><h3>Human có thể dạy chuyển động cho Action Expert</h3><p>Human và robot có target chuyển động cổ tay với cùng quy ước hình học. Cả hai cùng học motion qua Action Expert; robot vẫn có loss action riêng để điều khiển đúng GR1.</p><div class="plan-common-motion"><div><strong>Human</strong><span>Tracked wrist poses</span></div><div><strong>Robot</strong><span>Measured wrist poses</span></div><p>Target cổ tay cùng frame / timing / masks</p><strong>Common motion objective → shared Action Expert</strong><small>Native robot action objective giữ riêng</small></div><p class="plan-note">RGB-only không đủ cho motor pilot này. Human wrist không là robot joint labels; chưa có nhãn contact thì không nhận đã học lực gắp.</p></div></div><details class="opening-more"><summary>Recipe human: target, loss và gradient cụ thể<span>Một candidate để kiểm; không mặc định shared trunk sẽ transfer tốt.</span></summary><div class="opening-map-detail"><p><strong>Target:</strong> future wrist pose trong camera frame tại input time; translation 3D + rotation 6D mỗi tay, tối đa 18D và validity masks. Quy ước: <code>T_camera(t)_wrist(t+k) = inverse(T_world_camera(t)) × T_world_wrist(t+k)</code>. Robot target lấy từ future measured state qua FK/readback. Future pose chỉ là offline supervision.</p><p><strong>Bridge:</strong> human state adapter, common motion encoder/decoder và shared Action Expert trunk; native robot action encoder/decoder giữ riêng. Các nhánh phải có conditioning, normalization, noise/time conventions và checkpoint loading đã kiểm. Không gán human targets vào robot 29D.</p><p><strong>Loss:</strong> <code>L_robot_action + λ_RW L_robot_wrist + λ_H L_human_wrist</code>; coefficients chốt trên development. Units và normalization chung dùng robot train/development, không lấy final hoặc để human labels đổi chuẩn của control. Human pilot freeze VLM ở cả hai nhánh đối chứng để kiểm supervision trên Action Expert. Kiểm actual gradient/update và reload; wrist loss giảm chưa đủ kết luận robot tốt hơn.</p><p><strong>Đối chứng:</strong> R_common và R_common + H cùng architecture, robot wrist objective, parent, robot budget và VLM freeze. Muốn tách khỏi extra compute cần control riêng. Source hoặc bridge không đạt gate thì giữ chưa tích hợp.</p><a href="https://research.nvidia.com/labs/gear/egoscale/" target="_blank" rel="noopener">Tiền lệ common wrist representation: EgoScale →</a></div></details>`;}

function planRecipeSteps(items){return `<ol class="plan-recipe-steps">${items.map((s,i)=>`<li><span>0${i+1}</span><strong>${s}</strong></li>`).join('')}</ol>`;}
function planStudyMarkup(source){const human=source==='H';return `<span class="opening-kicker">PHÉP SO CẦN CHẠY</span><div class="plan-comparison"><div><small>Đối chứng</small><strong>${human?'R_common':'R'}</strong><span>${human?'Robot + common wrist objective':'Pretrained base + mẫu robot'}</span></div><span class="plan-versus">↔</span><div><small>Candidate</small><strong>${human?'R_common + H':source==='R'?'Nguồn đủ điều kiện':'R + S'}</strong><span>${human?'Thêm human motion hợp lệ':source==='R'?'Mở pilot sau baseline':'Thêm quỹ đạo sim qua QA'}</span></div></div><p>Cùng robot-data budget và ngưỡng đạt task; ghi toàn bộ công và compute bổ sung. ${human?'Giữ objective phụ ở cả hai nhánh để không quy gain của objective thành gain của human.':'Pilot một budget kiểm quality gain; cần thêm budget curve để kết luận giảm mẫu robot.'}</p><div class="plan-results"><span>Chất lượng <b>Chưa đo</b></span><span>Tổng công <b>Chưa đo</b></span><span>Tiết kiệm <b>Chưa kết luận</b></span></div>`;}

function openingTraceFlow(){return `<div class="plan-trace-tabs" role="group" aria-label="Xem bằng chứng tại từng ranh giới">${PLAN_TRACES.map((t,i)=>`<button type="button" data-plan-trace="${t.id}" aria-pressed="${i===0}" aria-controls="plan-trace-detail"><span>0${i+1}</span><strong>${t.label}</strong><small>${t.summary}</small></button>`).join('')}</div><div class="plan-trace-detail" id="plan-trace-detail" aria-live="polite"></div>`;}
function planTraceDetail(id){const t=PLAN_TRACES.find(t=>t.id===id);return `<span class="plan-chip">DẤU VẾT NATIVE CẦN THU · CHƯA CÓ SỐ ĐO</span><h3>${t.title}</h3><p>${t.body}</p><p class="plan-trace-check"><strong>Phép kiểm:</strong> ${t.check}</p>`;}

function openingQualityCost(){return `<section class="plan-quality" id="quality-cost" aria-labelledby="quality-cost-title"><header><span class="opening-kicker">KHI NÀO ĐƯỢC NHẬN LÀ CẢI THIỆN?</span><h2 id="quality-cost-title">Đạt cùng ngưỡng chất lượng.<br>Giảm tổng công phát triển.</h2><p>Chỉ ít robot demos hơn chưa đủ. Công xử lý human, sinh synthetic, QA, tích hợp, training và đánh giá đều đi vào phép so.</p></header><div class="plan-quality-grid"><article><span>01 · CHẤT LƯỢNG</span><h3>Kiểm cả task và điều kiện đang tốt</h3><p>Natural starts, chuyển tiếp, regression, unknown và timeout. Freeze model / recipe / scorer rồi dùng final giữ riêng; không lấy final để sửa model cùng vòng.</p></article><article><span>02 · TỔNG CÔNG</span><h3>Tính cả chi phí bổ sung</h3><p>Thu + reset + xử lý nguồn + generation/rejects + QA + train/retries + phép kiểm + evaluation. Setup lần đầu và công lặp lại báo riêng; thiếu số đo giữ unknown.</p></article><article><span>03 · DÙNG LẠI</span><h3>Task thứ hai kiểm khả năng mở rộng</h3><p>Trên cùng robot, ghi phần dùng lại và phần phải xây lại: TaskSpec, binding, scorer, dữ liệu và công integration. Robot khác có nghiệm thu riêng.</p></article></div><details class="opening-more"><summary>Ngưỡng thử và kế hoạch final đề xuất<span>Cần chốt trước thực nghiệm; chưa phải kết quả robot.</span></summary><div class="opening-map-detail"><p>MVP sim đề xuất full-task quality ≥ 90% trong domain đã khóa; final 100 independent scene starts, có coverage/regression và uncertainty. Nếu dùng exact binomial lower bound một phía 95%, phải kiểm assumptions về sampling trước. Owner chốt quality/cycle/domain và RunPlan trước freeze; chưa là chuẩn sản xuất.</p><p>Đạt cùng ngưỡng acceptance không tự là statistical equivalence. Muốn claim ít robot data cần budgets khác; muốn quy gain cho source cần compute controls phù hợp. Saving chỉ nhận khi baseline và candidate đều đáp ứng task, các chi phí quan trọng đã đo và setup không double-count.</p></div></details><div class="plan-handover"><div><strong>Bản triển khai A1 đầy đủ</strong><p>TaskSpec · robot/synthetic/human recipes · example lỗi · quality/cost gates · ledger chưa có số đo.</p></div><a class="button" href="assets/skill-a1-plan.zip" download>Tải bản triển khai ↓</a></div></section>`;}

function initSkillPlan(signal){const root=document.querySelector('.idea-overview');if(!root)return;
 function showSource(source){root.querySelectorAll('[data-plan-source]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.planSource===source)));root.querySelector('#source-recipe-body').innerHTML=planRecipeBody(source);root.querySelector('#source-study').innerHTML=planStudyMarkup(source);}
 function showTrace(id){root.querySelectorAll('[data-plan-trace]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.planTrace===id)));root.querySelector('#plan-trace-detail').innerHTML=planTraceDetail(id);}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.planSource)showSource(b.dataset.planSource);if(b.dataset.planTrace)showTrace(b.dataset.planTrace);},{signal});showSource('S');showTrace('input');
}
